def _to_xp(self, arr: Any, xp: Any, ref_arr: Any) -> Any:
    return xp.asarray(arr, device=array_api_compat.device(ref_arr))

def _masked_type_values(self, mask: Any, atype: Any, xp: Any) -> Any:
    """Look up per-type ``mask`` values by atom type.

    Padded batch entries carry negative types (usually ``-1``); they are
    not physical atoms, so their mask value must be exactly zero instead
    of whatever a wrapped or clamped index would return.
    """
    safe_atype = xp.where(atype < 0, xp.zeros_like(atype), atype)
    values = mask[safe_atype]
    return xp.where(atype < 0, xp.zeros_like(values), values)

extended_spin_dist = extended_spin * xp.reshape(
    self._masked_type_values(vsm, extended_atype, xp), (nframes, nall, 1)
)

atomic_mask = xp.reshape(
    self._masked_type_values(mask, atype, xp), (nframes, nloc, 1)
)

atomic_mask = xp.reshape(
    self._masked_type_values(mask, extended_atype, xp), (nframes, nall, 1)
)

