def _lookup_type_values(values: torch.Tensor, atype: torch.Tensor) -> torch.Tensor:
    flat_atype = torch.clamp_min(atype.reshape(-1).to(dtype=torch.long), 0)
    looked_up = torch.index_select(values.to(atype.device), 0, flat_atype).view(
        atype.shape
    )
    # Padded batch entries carry negative types (usually -1); they are not
    # physical atoms, so their mask value must be exactly zero instead of the
    # clamped-index value.
    return torch.where(atype < 0, torch.zeros_like(looked_up), looked_up)
